variables.value:
[{
  group: "Period",
  value: "month",
  label: "Month",
  description: "Billing month bucket (YYYY-MM)",
  sql: "TO_CHAR(amf.time_period, 'YYYY-MM') AS \"month\""
}, {
  group: "Period",
  value: "statementDate",
  label: "Statement Date",
  description: "Date associated with invoice date.",
  sql: "TO_CHAR(amf.statement_date, 'YYYY-MM-DD') AS \"statementDate\""
}, {
  group: "Period",
  value: "startDate",
  label: "Service Start",
  description: "Date associated with service start date.",
  sql: "TO_CHAR(amf.start_date, 'YYYY-MM-DD') AS \"startDate\""
}, {
  group: "Period",
  value: "endDate",
  label: "Service End",
  description: "Date associated with service end date.",
  sql: "TO_CHAR(amf.end_date, 'YYYY-MM-DD') AS \"endDate\""
}, {
  group: "Period",
  value: "daysOfService",
  label: "Days of Service",
  description: "Number of days associated with days of service.",
  sql: "amf.days_of_service AS \"daysOfService\""
}, {
  group: "Customer",
  value: "customerName",
  label: "Customer Name",
  description: "Name of the customer the report is being run for",
  sql: "(SELECT cs.name FROM bill_management_v2.customers_search cs WHERE cs.id = amf.customer_id) AS \"customerName\""
}, {
  group: "Location",
  value: "location",
  label: "Location",
  description: "Location name",
  sql: "l.name AS \"location\""
}, {
  group: "Location",
  value: "locationId",
  label: "Location ID (internal)",
  description: "UBM's own database id for the location, e.g. 113614. For the site number that appears on your reports, use Location Number.",
  sql: "l.id AS \"locationId\""
}, {
  group: "Location",
  value: "locationAddress",
  label: "Location Address",
  description: "Street address of the location",
  sql: "l.address AS \"locationAddress\""
}, {
  group: "Location",
  value: "locationCity",
  label: "City",
  description: "Location city",
  sql: "l.city AS \"locationCity\""
}, {
  group: "Location",
  value: "locationState",
  label: "State/Province",
  description: "Location state or province, written the way the client's reports write it — UBM stores US-AK, this reports AK. The ISO country prefix is dropped where there is one; anything else passes through as stored.",
  sql: "CASE WHEN l.state ~ '^[A-Za-z]{2}-' THEN substring(l.state from 4) ELSE l.state END AS \"locationState\""
}, {
  group: "Location",
  value: "locationCountry",
  label: "Country",
  description: "Location country, spelled out the way the client's reports write it — UBM stores US, this reports United States. An unrecognised code passes through as stored.",
  sql: "CASE upper(btrim(l.country)) WHEN 'US' THEN 'United States' WHEN 'USA' THEN 'United States' WHEN 'CA' THEN 'Canada' WHEN 'CAN' THEN 'Canada' WHEN 'MX' THEN 'Mexico' WHEN 'GB' THEN 'United Kingdom' WHEN 'UK' THEN 'United Kingdom' ELSE l.country END AS \"locationCountry\""
}, {
  group: "Location",
  value: "locationZip",
  label: "Location Zip",
  description: "Location postal / ZIP code",
  sql: "l.postcode AS \"locationZip\""
}, {
  group: "Location",
  value: "locationPhone",
  label: "Location Phone",
  description: "Phone number recorded against the site. Source: location_detail.location_phone — the locations table holds no phone number of its own. Empty for this customer: 0 of 268 sites carry one, measured 2026-08-11, where the client's own Location Detail has a number for most sites. Offered rather than loaded for that reason; it will fill in if UBM ever loads the numbers.",
  sql: "lt.location_phone AS \"locationPhone\""
}, {
  group: "Location",
  value: "locationStatus",
  label: "Location Status",
  description: "Status of the site. UBM records an open site as Operational; this is reported as Active to match the client's reports. Closed / Inactive / Terminated report as Inactive, and any other value passes through as UBM stores it.",
  sql: "CASE WHEN lower(btrim(lt.location_status)) IN ('operational','active','open') THEN 'Active' WHEN lower(btrim(lt.location_status)) IN ('closed','inactive','terminated','cancelled','canceled') THEN 'Inactive' ELSE lt.location_status END AS \"locationStatus\""
}, {
  group: "Location",
  value: "buildingType",
  label: "Building Type",
  description: "Type or category of location building type.",
  sql: "l.building_type AS \"buildingType\""
}, {
  group: "Location",
  value: "squareFeet",
  label: "Square Feet",
  description: "Location floor area (sq ft)",
  sql: "l.square_feet AS \"squareFeet\""
}, {
  group: "Location",
  value: "locationNumber",
  label: "Location Number",
  description: "Site number, e.g. 0115 — the number your own reports refer to a location by.",
  sql: "lt.location_number AS \"locationNumber\""
}, {
  group: "Vendor / Account",
  value: "vendor",
  label: "Vendor",
  description: "Vendor name — the customer's pretty name where one is set, otherwise the global pretty name, otherwise the vendor's plain name. A pretty name that is only the vendor code respelled — Adaya for ADAYA — is skipped, so the real name wins. A vendor code that maps to more than one name in providers_vendors resolves to no name rather than an arbitrary one, and the code is shown instead.",
  sql: "COALESCE(NULLIF(btrim(cvpn.pretty_name), ''), CASE WHEN lower(regexp_replace(btrim(v.pretty_name), '[^A-Za-z0-9]', '', 'g')) <> lower(regexp_replace(amf.vendor_code, '[^A-Za-z0-9]', '', 'g')) THEN NULLIF(btrim(v.pretty_name), '') END, NULLIF(btrim(cpv.name), ''), NULLIF(btrim(pv.name), ''), amf.vendor_code) AS \"vendor\""
}, {
  group: "Vendor / Account",
  value: "vendorNameAp",
  label: "Vendor Name (AP)",
  description: "Remittance / accounts-payable name for the vendor — the name an ERP such as JDE is most likely to expect",
  sql: "COALESCE(NULLIF(btrim(cpv.remittance_name), ''), NULLIF(btrim(pv.remittance_name), '')) AS \"vendorNameAp\""
}, {
  group: "Vendor / Account",
  value: "vendorCode",
  label: "Vendor Code",
  description: "Vendor code (stable join key)",
  sql: "amf.vendor_code AS \"vendorCode\""
}, {
  group: "Vendor / Account",
  value: "vendorId",
  label: "Vendor ID",
  description: "Engie's FIQ Vendor ID, held as a vendor attribute in reports_vendors under the key Vendor Code — 45910 for Access Gas Services, which is the number their report shows. Not vendors.id, which is UBM's own key and a different number entirely.",
  sql: "rv.fiq_vendor_id AS \"vendorId\""
}, {
  group: "Vendor address",
  value: "vendorAddress1",
  label: "Vendor Address 1",
  description: "First line of the vendor's remittance address. Source: (remittance_address).line_1, from the customer's own vendor record where there is one.",
  sql: "COALESCE(NULLIF(btrim((cpv.remittance_address).line_1), ''), NULLIF(btrim((pv.remittance_address).line_1), '')) AS \"vendorAddress1\""
}, {
  group: "Vendor address",
  value: "vendorAddress2",
  label: "Vendor Address 2",
  description: "Second line of the vendor's remittance address. Source: (remittance_address).line_2. Lines 3 and 4 exist in UBM and can be added if a vendor uses them.",
  sql: "COALESCE(NULLIF(btrim((cpv.remittance_address).line_2), ''), NULLIF(btrim((pv.remittance_address).line_2), '')) AS \"vendorAddress2\""
}, {
  group: "Vendor address",
  value: "vendorCity",
  label: "Vendor City",
  description: "Vendor's city. Source: (remittance_address).city.",
  sql: "COALESCE(NULLIF(btrim((cpv.remittance_address).city), ''), NULLIF(btrim((pv.remittance_address).city), '')) AS \"vendorCity\""
}, {
  group: "Vendor address",
  value: "vendorState",
  label: "Vendor State/Province",
  description: "Vendor's state or province. Source: (remittance_address).state.",
  sql: "COALESCE(NULLIF(btrim((cpv.remittance_address).state), ''), NULLIF(btrim((pv.remittance_address).state), '')) AS \"vendorState\""
}, {
  group: "Vendor address",
  value: "vendorZip",
  label: "Vendor Postal Code",
  description: "Vendor's postal / ZIP code. Source: (remittance_address).post_code.",
  sql: "COALESCE(NULLIF(btrim((cpv.remittance_address).post_code), ''), NULLIF(btrim((pv.remittance_address).post_code), '')) AS \"vendorZip\""
}, {
  group: "Vendor address",
  value: "vendorCountry",
  label: "Vendor Country",
  description: "Vendor's country. Source: (remittance_address).country.",
  sql: "COALESCE(NULLIF(btrim((cpv.remittance_address).country), ''), NULLIF(btrim((pv.remittance_address).country), '')) AS \"vendorCountry\""
}, {
  group: "Vendor address",
  value: "vendorAddress",
  label: "Vendor Address",
  description: "The vendor's remittance address on one line — the six address columns joined with commas, blanks skipped. Each part resolves exactly as its own column does, so this reads the same as those columns concatenated.",
  sql: "NULLIF(concat_ws(', ', NULLIF(btrim(COALESCE((cpv.remittance_address).line_1, (pv.remittance_address).line_1)), ''), NULLIF(btrim(COALESCE((cpv.remittance_address).line_2, (pv.remittance_address).line_2)), ''), NULLIF(btrim(COALESCE((cpv.remittance_address).city, (pv.remittance_address).city)), ''), NULLIF(btrim(COALESCE((cpv.remittance_address).state, (pv.remittance_address).state)), ''), NULLIF(btrim(COALESCE((cpv.remittance_address).post_code, (pv.remittance_address).post_code)), ''), NULLIF(btrim(COALESCE((cpv.remittance_address).country, (pv.remittance_address).country)), '')), '') AS \"vendorAddress\""
}, {
  group: "Vendor address",
  value: "vendorPhone",
  label: "Vendor Phone Business",
  description: "Vendor's main business phone. Source: main_phone, from the customer's own vendor record where there is one, otherwise the global one — the same priority the vendor name and address use. UBM records no phone extension, so the client's Vendor Phone Extension has no source.",
  sql: "COALESCE(NULLIF(btrim(cpv.main_phone), ''), NULLIF(btrim(pv.main_phone), '')) AS \"vendorPhone\""
}, {
  group: "Vendor / Account",
  value: "accountNumber",
  label: "Account #",
  description: "Utility account number as it appears on the bill",
  sql: "va.account_code AS \"accountNumber\""
}, {
  group: "Vendor / Account",
  value: "accountStatus",
  label: "Account Status",
  description: "Status of the utility account itself — not the location's status. Closed / Inactive / Terminated report as Inactive. UBM's other value is Unknown, meaning no closure has been recorded, and it is passed through rather than read as Active: measured against the client's deactivation list, a large share of the accounts they have deactivated still read Unknown here. Treat Unknown as unreported, not as active.",
  sql: "CASE WHEN lower(btrim(vas.account_status)) IN ('closed','inactive','terminated','cancelled','canceled') THEN 'Inactive' WHEN lower(btrim(vas.account_status)) IN ('active','open') THEN 'Active' ELSE vas.account_status END AS \"accountStatus\""
}, {
  group: "Vendor / Account",
  value: "accountCreatedDate",
  label: "Account Created Date",
  description: "First month the account was billed — UBM's closest equivalent to the client's FIQ Account Creation Date. UBM holds no account opening date: virtual_accounts.account_opened and virtual_accounts_status.account_opened are both empty, and created_at is the date UBM loaded the record, not the date the account opened.",
  sql: "TO_CHAR(af.first_period, 'YYYY-MM-DD') AS \"accountCreatedDate\""
}, {
  group: "Vendor / Account",
  value: "lastBillDate",
  label: "Date of Last Bill",
  description: "Statement date of the most recent bill UBM holds for the account. Taken per account number, site and vendor, the same grain as Account Created Date, so an account number billed for several commodities reports one date rather than one per service. Note UBM runs some billing cycles behind the client's own reports, so this will read earlier than theirs.",
  sql: "TO_CHAR(af.last_bill_date, 'YYYY-MM-DD') AS \"lastBillDate\""
}, {
  group: "Vendor / Account",
  value: "accountActivityDate",
  label: "Account Activity Date",
  description: "Date the account's current status took effect — the deactivation date where the account has one, otherwise the first month it was billed. Source: virtual_accounts_status.account_closed, falling back to the feed because no opening date is recorded.",
  sql: "TO_CHAR(COALESCE(vas.account_closed, af.first_period), 'YYYY-MM-DD') AS \"accountActivityDate\""
}, {
  group: "Vendor / Account",
  value: "cleanAccountNumber",
  label: "Clean Account #",
  description: "Account number with punctuation removed, for matching against systems that store it unformatted. Derived from Account # — UBM stores no clean account number of its own.",
  sql: "regexp_replace(va.account_code, '[^A-Za-z0-9]', '', 'g') AS \"cleanAccountNumber\""
}, {
  group: "Vendor / Account",
  value: "summaryAccount",
  label: "Summary Account",
  description: "Account this one rolls up to, where it is billed under a parent. Source: virtual_accounts.client_account, shown only where it differs from the account's own number — an account billed in its own right leaves this blank, which is most of them.",
  sql: "NULLIF(va.client_account, va.account_code) AS \"summaryAccount\""
}, {
  group: "Vendor / Account",
  value: "meterSerial",
  label: "Meter #",
  description: "Meter serial number recorded against the account. Source: virtual_accounts.meter_serial.",
  sql: "va.meter_serial AS \"meterSerial\""
}, {
  group: "GL",
  value: "glCode",
  label: "Customer GL Number",
  description: "GL code charged for this account, one row per code. Source: the GL Code 1–6 account attributes, unpivoted so an account split across several GL codes reports as several rows. Reported exactly as UBM stores it, including any trailing .000 — the client's exports carry the same suffix, even where Excel's number formatting hides it.",
  sql: "glr.gl_code AS \"glCode\""
}, {
  group: "GL",
  value: "glAllocation",
  label: "GL Allocation %",
  description: "Share of the account allocated to this row's GL code, as a percentage — 51.25 means 51.25%, and an account charged to a single GL reads 100. The scale is UBM's own, unchanged. Note the client's own exports format these cells as percentages, so Excel shows 51.25% while storing 0.5125 — the same number, not a different scale.",
  sql: "CASE WHEN btrim(glr.gl_allocation) ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN btrim(glr.gl_allocation)::numeric END AS \"glAllocation\""
}, {
  group: "Vendor / Account",
  value: "billType",
  label: "Bill Type",
  description: "Type or category of bill type.",
  sql: "amf.bill_type AS \"billType\""
}, {
  group: "Line item",
  source: "lineItems",
  value: "serviceDescription",
  label: "Service Description",
  description: "What the charge line is, as UBM classifies it — Customer Charge (C), General Usage Charge (C), Late Fee (C). Source: analytics_billing_line_items.description. Note this is UBM's own wording: the client's reports show the vendor's text from the bill (Elec Cust Chrg, G Cust Chrg), which UBM does not keep.",
  sql: "amf.line_description AS \"serviceDescription\""
}, {
  group: "Line item",
  source: "lineItems",
  value: "serviceAlias",
  label: "Service Alias",
  description: "The vendor's own label for the charge line, as printed on the bill — Energy, Fuel, Gross Revenue Tax, Purchased Power. Source: analytics_billing_line_items.value, which despite the column name holds text rather than a number. This is the client's Service Alias column and the values match theirs.",
  sql: "amf.line_value AS \"serviceAlias\""
}, {
  group: "Line item",
  source: "lineItems",
  value: "lineCode",
  label: "Charge Code",
  description: "UBM's code for the charge line — CUSTOMERCHARGE, CHG_CHARGE, LATEFEE. Source: analytics_billing_line_items.code.",
  sql: "amf.line_code AS \"lineCode\""
}, {
  group: "Line item",
  source: "lineItems",
  value: "lineCategory",
  label: "Charge Category",
  description: "Which family the charge falls in — Usage Charges, Customer Charges, Other Charges, Taxes. Source: analytics_billing_line_items.category. This is where the client's Tax and Misc Charges service types live, since UBM does not treat those as commodities.",
  sql: "amf.line_category AS \"lineCategory\""
}, {
  group: "Late fee",
  value: "billDate",
  label: "Bill Date",
  description: "Statement date of the bill this row is for. Source: the earliest statement_date on the bill's feed rows. Distinct from the Period group's Statement Date, which is per monthly slice and would split a bill into several rows.",
  sql: "TO_CHAR(lf.bill_date, 'YYYY-MM-DD') AS \"billDate\""
}, {
  group: "Late fee",
  value: "billAmount",
  label: "Bill Amount",
  description: "Total charged on the bill. Source: the sum of analytics_monthly_feed.total_charges across the bill's monthly slices, so it is the whole bill rather than one month's share.",
  sql: "lf.bill_amount AS \"billAmount\""
}, {
  group: "Late fee",
  value: "lateFeeAmount",
  label: "Late Fee Amount",
  description: "Net late fee on this bill — fees charged less any recouped. Source: analytics_billing_line_items where code is LATEFEE. The main UBM app splits the same three ways; Fee Charged and Fee Recouped are offered separately.",
  sql: "lf.late_fee AS \"lateFeeAmount\""
}, {
  group: "Late fee",
  value: "lateFeeCharged",
  label: "Late Fee Charged",
  description: "Late fees charged on this bill, positive lines only, before any recoupment.",
  sql: "lf.late_fee_charged AS \"lateFeeCharged\""
}, {
  group: "Late fee",
  value: "lateFeeRecouped",
  label: "Late Fee Recouped",
  description: "Late fees credited back on this bill, negative lines only. Reported separately rather than netted away silently, matching the main UBM app.",
  sql: "lf.late_fee_recouped AS \"lateFeeRecouped\""
}, {
  group: "Late fee",
  value: "lateFeePct",
  label: "Late Fee % of Charges",
  description: "Net late fee as a percentage of the bill total — 5 means the fee was 5% of what was billed. Matches the Late fee/charges column on the main UBM app's Bill Health report.",
  sql: "((lf.late_fee / NULLIF(lf.bill_amount, 0)) * 100) AS \"lateFeePct\""
}, {
  group: "Late fee",
  value: "recoupedPct",
  label: "Recouped % of Late Fees",
  description: "How much of the fee charged was credited back, as a percentage. 100 means the whole fee was recouped. Matches the Recouped/late fees column on the main UBM app's Bill Health report.",
  sql: "((ABS(lf.late_fee_recouped) / NULLIF(lf.late_fee_charged, 0)) * 100) AS \"recoupedPct\""
}, {
  group: "Late fee",
  value: "prevBillDate",
  label: "Prev Bill Date",
  description: "Statement date of the account's previous bill, taken in bill-date order.",
  sql: "TO_CHAR(lf.prev_bill_date, 'YYYY-MM-DD') AS \"prevBillDate\""
}, {
  group: "Late fee",
  value: "prevBillAmount",
  label: "Prev Bill Amount",
  description: "Total charged on the account's previous bill.",
  sql: "lf.prev_bill_amount AS \"prevBillAmount\""
}, {
  group: "Late fee",
  value: "prevBillReceiptDate",
  label: "Prev Bill Receipt Date",
  description: "Date the previous bill was received. Source: bill_records.received_on for that bill. Not reliable for this customer: 21,611 bills carry only 20 distinct received_on values, about 1,080 sharing each, and 92.8% are dated as received after they were already due. It is a bulk-load stamp on backfilled bills, genuine only on bills processed live. Measured 2026-08-13.",
  sql: "TO_CHAR(pbr.received_on, 'YYYY-MM-DD') AS \"prevBillReceiptDate\""
}, {
  group: "Late fee",
  value: "prevBillConsolidatedDate",
  label: "Prev Bill Consolidated Date",
  description: "Date the previous bill was consolidated into a payment batch. Source: batches.created_at, reached through bill_records.batch_id. A candidate rather than a confirmed mapping — batches also carries uploaded_at and downloaded_at, and which one the client means has not been checked against a known bill. Blank where the bill was never batched.",
  sql: "TO_CHAR(pbb.created_at, 'YYYY-MM-DD') AS \"prevBillConsolidatedDate\""
}, {
  group: "Late fee",
  value: "prevBillDueDate",
  label: "Prev Bill Due Date",
  description: "Date the previous bill was due. Source: bill_records.due_date for that bill.",
  sql: "TO_CHAR(pbr.due_date, 'YYYY-MM-DD') AS \"prevBillDueDate\""
}, {
  group: "Late fee",
  value: "daysUntilDue",
  label: "Days Until Due",
  description: "Days between receiving the previous bill and its due date — due date minus receipt date. The arithmetic is confirmed: it reproduces all 59 rows of the client's own Late Fees tab exactly. But it inherits the receipt date, which is not reliable here. Not reliable for this customer: 21,611 bills carry only 20 distinct received_on values, about 1,080 sharing each, and 92.8% are dated as received after they were already due. It is a bulk-load stamp on backfilled bills, genuine only on bills processed live. Measured 2026-08-13. So the column computes correctly and means nothing wherever that date is a load stamp, which is most of them.",
  sql: "(pbr.due_date::date - pbr.received_on::date) AS \"daysUntilDue\""
}, {
  group: "Bill record",
  value: "billId",
  label: "Engie Insight Bill ID",
  description: "UBM's own id for the bill behind this row. Source: analytics_monthly_feed.bill_id, no join needed.",
  sql: "amf.bill_id AS \"billId\""
}, {
  group: "Bill record",
  value: "billPdf",
  label: "Invoice PDF",
  description: "Link to the scanned bill, as an https URL that opens in a new tab. Source: bill_files.path for the bill's application/pdf file, a Google Cloud Storage object with the gs:// prefix rewritten to https://storage.googleapis.com/. A bill also carries a text/csv of its readings under observations/, which this ignores. Blank where UBM holds no PDF for the bill — the report builds the link, it does not check the file is reachable.",
  sql: "replace(bfile.path, 'gs://', 'https://storage.googleapis.com/') AS \"billPdf\""
}, {
  group: "Bill record",
  value: "vendorInvoice",
  label: "Vendor Invoice #",
  description: "Invoice number as the vendor wrote it. Source: bill_records.invoice_number, joined on the feed's own bill_record_id, so one bill record per row and no row multiplication.",
  sql: "br.invoice_number AS \"vendorInvoice\""
}, {
  group: "Bill record",
  value: "dueDate",
  label: "Due Date",
  description: "Date the bill was due. Source: bill_records.due_date.",
  sql: "TO_CHAR(br.due_date, 'YYYY-MM-DD') AS \"dueDate\""
}, {
  group: "Bill record",
  value: "receiptDate",
  label: "Receipt Date",
  description: "Date the bill was received. Source: bill_records.received_on. Not reliable for this customer: 21,611 bills carry only 20 distinct received_on values, about 1,080 sharing each, and 92.8% are dated as received after they were already due. It is a bulk-load stamp on backfilled bills, genuine only on bills processed live. Measured 2026-08-13.",
  sql: "TO_CHAR(br.received_on, 'YYYY-MM-DD') AS \"receiptDate\""
}, {
  group: "Bill",
  value: "billBeginDate",
  label: "Begin Date",
  description: "First day of the bill's service period, as billed. Source: account_history.start_date, which is bill-level — the monthly feed's Service Start is the start of a month's slice of that bill, not the bill itself.",
  sql: "TO_CHAR(ah.start_date, 'YYYY-MM-DD') AS \"billBeginDate\""
}, {
  group: "Bill",
  value: "billEndDate",
  label: "End Date",
  description: "Last day of the bill's service period, as billed. Source: account_history.end_date. A bill spanning a month end is one row here and two in the monthly feed.",
  sql: "TO_CHAR(ah.end_date, 'YYYY-MM-DD') AS \"billEndDate\""
}, {
  group: "Bill",
  value: "billServiceCost",
  label: "Service Cost",
  description: "Charges for the bill as billed, not spread across the months it covers. Source: account_history.subcharges — UBM's Subcharges family is per bill block, where the Charges family on the monthly feed is pro-rated.",
  sql: "ah.subcharges AS \"billServiceCost\""
}, {
  group: "Bill",
  value: "billQuantity",
  label: "Quantity (Billed)",
  description: "Consumption for the bill as billed. Source: account_history.consumption. The monthly feed's Total Consumption is the same quantity pro-rated across months, which is why it reads in fractions where the bill reads whole units.",
  sql: "CASE WHEN ah.bill_id IS NOT NULL THEN COALESCE(ah.consumption, 0) END AS \"billQuantity\""
}, {
  group: "Vendor / Account",
  value: "utilityType",
  label: "Service / Utility Type",
  description: "Commodity the account is billed for, spelled out the way the client's reports write it — UBM stores NATURALGAS, this reports Natural Gas. Note their reports also use this column for charge categories (Tax, Late Charges, Misc Charges), which UBM does not model as service types at all.",
  sql: "CASE upper(btrim(amf.utility_type)) WHEN 'ELECTRIC' THEN 'Electric' WHEN 'WATER' THEN 'Water' WHEN 'SEWER' THEN 'Sewer' WHEN 'NATURALGAS' THEN 'Natural Gas' WHEN 'FIREPROTECTION' THEN 'Fire Protection' WHEN 'STORMWATER' THEN 'Storm Water' WHEN 'IRRIGATION' THEN 'Irrigation' WHEN 'LIGHTING' THEN 'Lighting' WHEN 'REFUSE' THEN 'Refuse' WHEN 'SOLARPV' THEN 'Solar PV' WHEN 'CHILLEDWATER' THEN 'Chilled Water' WHEN 'PROPANE' THEN 'Propane' ELSE amf.utility_type END AS \"utilityType\""
}, {
  group: "Usage",
  value: "uom",
  label: "Unit of Measure",
  description: "Unit of measure for consumption (e.g. CCF, KWH)",
